530  bool ProcessGeneric(ots::FontFile *header,
   531                      ots::Font *font,
   532                      uint32_t signature,
   533                      ots::OTSStream *output,
   534                      const uint8_t *data, size_t length,
   535                      const std::vector<ots::TableEntry>& tables,
   536                      ots::Buffer& file) {
   537    const size_t data_offset = file.offset();
   538
   539    uint32_t uncompressed_sum = 0;
   540
   541    for (unsigned i = 0; i < font->num_tables; ++i) {
   542      // the tables must be sorted by tag (when taken as big-endian numbers).
   543      // This also remove the possibility of duplicate tables.
   544      if (i) {
   545        const uint32_t this_tag = tables[i].tag;
   546        const uint32_t prev_tag = tables[i - 1].tag;
   547        if (this_tag <= prev_tag) {
   548          OTS_WARNING_MSG_HDR("Table directory is not correctly ordered");
   549        }
   550      }
   551
   552      // all tag names must be built from printable ASCII characters
   553      if (!CheckTag(tables[i].tag)) {
   554        return OTS_FAILURE_MSG_TAG("invalid table tag", tables[i].tag);
   555      }
   556
   557      // tables must be 4-byte aligned
   558      if (tables[i].offset & 3) {
   559        return OTS_FAILURE_MSG_TAG("misaligned table", tables[i].tag);
   560      }
   561
   562      // and must be within the file
   563      if (tables[i].offset < data_offset || tables[i].offset >= length) {
   564        return OTS_FAILURE_MSG_TAG("invalid table offset", tables[i].tag);
   565      }
   566      // disallow all tables with a zero length
   567      if (tables[i].length < 1) {
   568        // Note: malayalam.ttf has zero length CVT table...
   569        return OTS_FAILURE_MSG_TAG("zero-length table", tables[i].tag);
   570      }
   571      // disallow all tables with a length > 1GB
   572      if (tables[i].length > 1024 * 1024 * 1024) {
   573        return OTS_FAILURE_MSG_TAG("table length exceeds 1GB", tables[i].tag);
   574      }
   575      // disallow tables where the uncompressed size is < the compressed size.
   576      if (tables[i].uncompressed_length < tables[i].length) {
   577        return OTS_FAILURE_MSG_TAG("invalid compressed table", tables[i].tag);
   578      }
   579      if (tables[i].uncompressed_length > tables[i].length) {
   580        // We'll probably be decompressing this table.
   581
   582        // disallow all tables which uncompress to > 30 MB
   583        if (tables[i].uncompressed_length > 30 * 1024 * 1024) {
   584          return OTS_FAILURE_MSG_TAG("uncompressed length exceeds 30MB", tables[i].tag);
   585        }
   586        if (uncompressed_sum + tables[i].uncompressed_length < uncompressed_sum) {
   587          return OTS_FAILURE_MSG_TAG("overflow of uncompressed sum", tables[i].tag);
   588        }
   589
   590        uncompressed_sum += tables[i].uncompressed_length;
   591      }
   592      // since we required that the file be < 1GB in length, and that the table
   593      // length is < 1GB, the following addtion doesn't overflow
   594      uint32_t end_byte = tables[i].offset + tables[i].length;
   595      // Tables in the WOFF file must be aligned 4-byte boundary.
   596      if (signature == OTS_TAG('w','O','F','F')) {
   597          end_byte = ots::Round4(end_byte);
   598      }
   599      if (!end_byte || end_byte > length) {
   600        return OTS_FAILURE_MSG_TAG("table overruns end of file", tables[i].tag);
   601      }
   602    }
   603
   604    // All decompressed tables uncompressed must be <= 30MB.
   605    if (uncompressed_sum > 30 * 1024 * 1024) {
   606      return OTS_FAILURE_MSG_HDR("uncompressed sum exceeds 30MB");
   607    }
   608
   609    // check that the tables are not overlapping.
   610    std::vector<std::pair<uint32_t, uint8_t> > overlap_checker;
   611    for (unsigned i = 0; i < font->num_tables; ++i) {
   612      overlap_checker.push_back(
   613          std::make_pair(tables[i].offset, static_cast<uint8_t>(1) /* start */));
   614      overlap_checker.push_back(
   615          std::make_pair(tables[i].offset + tables[i].length,
   616                         static_cast<uint8_t>(0) /* end */));
   617    }
   618    std::sort(overlap_checker.begin(), overlap_checker.end());
   619    int overlap_count = 0;
   620    for (unsigned i = 0; i < overlap_checker.size(); ++i) {
   621      overlap_count += (overlap_checker[i].second ? 1 : -1);
   622      if (overlap_count > 1) {
   623        return OTS_FAILURE_MSG_HDR("overlapping tables");
   624      }
   625    }
   626
   627    std::map<uint32_t, ots::TableEntry> table_map;
   628    for (unsigned i = 0; i < font->num_tables; ++i) {
   629      table_map[tables[i].tag] = tables[i];
   630    }
   631
   632    // Parse known tables first as we need to parse them in specific order.
   633    for (unsigned i = 0; ; ++i) {
   634      if (supported_tables[i].tag == 0) break;
   635
   636      uint32_t tag = supported_tables[i].tag;
   637      const auto &it = table_map.find(tag);
   638      if (it == table_map.cend()) {
   639        if (supported_tables[i].required) {
   640          return OTS_FAILURE_MSG_TAG("missing required table", tag);
   641        }
   642      } else {
   643        if (!font->ParseTable(it->second, data)) {
   644          return OTS_FAILURE_MSG_TAG("Failed to parse table", tag);
   645        }
   646      }
   647    }
   648
   649    // Then parse any tables left.
   650    for (const auto &table_entry : tables) {
   651      if (!font->GetTable(table_entry.tag)) {
   652        if (!font->ParseTable(table_entry, data)) {
   653          return OTS_FAILURE_MSG_TAG("Failed to parse table", table_entry.tag);
   654        }
   655      }
   656    }
   657
   658    if (font->GetTable(OTS_TAG_CFF)) {
   659      // font with PostScript glyph
   660      if (font->version != OTS_TAG('O','T','T','O')) {
   661        return OTS_FAILURE_MSG_HDR("wrong font version for PostScript glyph data");
   662      }
   663      if (font->GetTable(OTS_TAG_GLYF) || font->GetTable(OTS_TAG_LOCA)) {
   664        // mixing outline formats is not recommended
   665        return OTS_FAILURE_MSG_HDR("font contains both PS and TT glyphs");
   666      }
   667    } else {
   668      if (!font->GetTable(OTS_TAG_GLYF) || !font->GetTable(OTS_TAG_LOCA)) {
   669        // No TrueType glyph found.
   670        //
   671        // We don't sanitize bitmap tables, but don’t reject bitmap-only fonts if
   672        // we are asked to pass them thru.
   673        // Also don’t reject if we are asked to pass glyf/loca thru.
   674        if (!font->GetTable(OTS_TAG('C','B','D','T')) &&
   675            !font->GetTable(OTS_TAG('C','B','L','C'))) {
   676          return OTS_FAILURE_MSG_HDR("no supported glyph shapes table(s) present");
   677        }
   678      }
   679    }
   680
   681    uint16_t num_output_tables = 0;
   682    for (const auto &it : table_map) {
   683      ots::Table *table = font->GetTable(it.first);
   684      if (table != NULL && table->ShouldSerialize())
   685        num_output_tables++;
   686    }
   687
   688    uint16_t max_pow2 = 0;
   689    while (1u << (max_pow2 + 1) <= num_output_tables) {
   690      max_pow2++;
   691    }
   692    const uint16_t output_search_range = (1u << max_pow2) << 4;
   693
   694    // most of the errors here are highly unlikely - they'd only occur if the
   695    // output stream returns a failure, e.g. lack of space to write
   696    output->ResetChecksum();
   697    if (!output->WriteU32(font->version) ||
   698        !output->WriteU16(num_output_tables) ||
   699        !output->WriteU16(output_search_range) ||
   700        !output->WriteU16(max_pow2) ||
   701        !output->WriteU16((num_output_tables << 4) - output_search_range)) {
   702      return OTS_FAILURE_MSG_HDR("error writing output");
   703    }
   704    const uint32_t offset_table_chksum = output->chksum();
   705
   706    const size_t table_record_offset = output->Tell();
   707    if (!output->Pad(16 * num_output_tables)) {
   708      return OTS_FAILURE_MSG_HDR("error writing output");
   709    }
   710
   711    std::vector<ots::TableEntry> out_tables;
   712
   713    size_t head_table_offset = 0;
   714    for (const auto &it : table_map) {
   715      uint32_t input_offset = it.second.offset;
   716      const auto &ot = header->table_entries.find(input_offset);
   717      if (ot != header->table_entries.end()) {
   718        ots::TableEntry out = ot->second;
   719        if (out.tag == OTS_TAG('h','e','a','d')) {
   720          head_table_offset = out.offset;
   721        }
   722        out_tables.push_back(out);
   723      } else {
   724        ots::TableEntry out;
   725        out.tag = it.first;
   726        out.offset = output->Tell();
   727
   728        if (out.tag == OTS_TAG('h','e','a','d')) {
   729          head_table_offset = out.offset;
   730        }
   731
   732        ots::Table *table = font->GetTable(out.tag);
   733        if (table != NULL && table->ShouldSerialize()) {
   734          output->ResetChecksum();
   735          if (!table->Serialize(output)) {
   736            return OTS_FAILURE_MSG_TAG("failed to serialize table", out.tag);
   737          }
   738
   739          const size_t end_offset = output->Tell();
   740          if (end_offset <= out.offset) {
   741            // paranoid check. |end_offset| is supposed to be greater than the offset,
   742            // as long as the Tell() interface is implemented correctly.
   743            return OTS_FAILURE_MSG_HDR("error writing output");
   744          }
   745          out.length = end_offset - out.offset;
   746
   747          // align tables to four bytes
   748          if (!output->Pad((4 - (end_offset & 3)) % 4)) {
   749            return OTS_FAILURE_MSG_HDR("error writing output");
   750          }
   751          out.chksum = output->chksum();
   752          out_tables.push_back(out);
   753          header->table_entries[input_offset] = out;
   754        }
   755      }
   756    }
   757
   758    const size_t end_of_file = output->Tell();
   759
   760    // Need to sort the output tables for inclusion in the file
   761    std::sort(out_tables.begin(), out_tables.end());
   762    if (!output->Seek(table_record_offset)) {
   763      return OTS_FAILURE_MSG_HDR("error writing output");
   764    }
   765
   766    output->ResetChecksum();
   767    uint32_t tables_chksum = 0;
   768    for (unsigned i = 0; i < out_tables.size(); ++i) {
   769      if (!output->WriteU32(out_tables[i].tag) ||
   770          !output->WriteU32(out_tables[i].chksum) ||
   771          !output->WriteU32(out_tables[i].offset) ||
   772          !output->WriteU32(out_tables[i].length)) {
   773        return OTS_FAILURE_MSG_HDR("error writing output");
   774      }
   775      tables_chksum += out_tables[i].chksum;
   776    }
   777    const uint32_t table_record_chksum = output->chksum();
   778
   779    // http://www.microsoft.com/typography/otspec/otff.htm
   780    const uint32_t file_chksum
   781        = offset_table_chksum + tables_chksum + table_record_chksum;
   782    const uint32_t chksum_magic = static_cast<uint32_t>(0xb1b0afba) - file_chksum;
   783
   784    // seek into the 'head' table and write in the checksum magic value
   785    if (!head_table_offset) {
   786      return OTS_FAILURE_MSG_HDR("internal error!");
   787    }
   788    if (!output->Seek(head_table_offset + 8)) {
   789      return OTS_FAILURE_MSG_HDR("error writing output");
   790    }
   791    if (!output->WriteU32(chksum_magic)) {
   792      return OTS_FAILURE_MSG_HDR("error writing output");
   793    }
   794
   795    if (!output->Seek(end_of_file)) {
   796      return OTS_FAILURE_MSG_HDR("error writing output");
   797    }
   798
   799    return true;
   800  }
