   813  bool Font::ParseTable(const TableEntry& table_entry, const uint8_t* data) {
   814    uint32_t tag = table_entry.tag;
   815    TableAction action = GetTableAction(file, tag);
   816    if (action == TABLE_ACTION_DROP) {
   817      return true;
   818    }
   819
   820    const auto &it = file->tables.find(table_entry);
   821    if (it != file->tables.end()) {
   822      m_tables[tag] = it->second;
   823      return true;
   824    }
   825
   826    Table *table = NULL;
   827    bool ret = false;
   828
   829    if (action == TABLE_ACTION_PASSTHRU) {
   830      table = new TablePassthru(this, tag);
   831    } else {
   832      switch (tag) {
   833        case OTS_TAG_CFF:  table = new OpenTypeCFF(this,  tag); break;
   834        case OTS_TAG_CMAP: table = new OpenTypeCMAP(this, tag); break;
   835        case OTS_TAG_CVT:  table = new OpenTypeCVT(this,  tag); break;
   836        case OTS_TAG_FPGM: table = new OpenTypeFPGM(this, tag); break;
   837        case OTS_TAG_GASP: table = new OpenTypeGASP(this, tag); break;
   838        case OTS_TAG_GDEF: table = new OpenTypeGDEF(this, tag); break;
   839        case OTS_TAG_GLYF: table = new OpenTypeGLYF(this, tag); break;
   840        case OTS_TAG_GPOS: table = new OpenTypeGPOS(this, tag); break;
   841        case OTS_TAG_GSUB: table = new OpenTypeGSUB(this, tag); break;
   842        case OTS_TAG_HDMX: table = new OpenTypeHDMX(this, tag); break;
   843        case OTS_TAG_HEAD: table = new OpenTypeHEAD(this, tag); break;
   844        case OTS_TAG_HHEA: table = new OpenTypeHHEA(this, tag); break;
   845        case OTS_TAG_HMTX: table = new OpenTypeHMTX(this, tag); break;
   846        case OTS_TAG_KERN: table = new OpenTypeKERN(this, tag); break;
   847        case OTS_TAG_LOCA: table = new OpenTypeLOCA(this, tag); break;
   848        case OTS_TAG_LTSH: table = new OpenTypeLTSH(this, tag); break;
   849        case OTS_TAG_MATH: table = new OpenTypeMATH(this, tag); break;
   850        case OTS_TAG_MAXP: table = new OpenTypeMAXP(this, tag); break;
   851        case OTS_TAG_NAME: table = new OpenTypeNAME(this, tag); break;
   852        case OTS_TAG_OS2:  table = new OpenTypeOS2(this,  tag); break;
   853        case OTS_TAG_POST: table = new OpenTypePOST(this, tag); break;
   854        case OTS_TAG_PREP: table = new OpenTypePREP(this, tag); break;
   855        case OTS_TAG_VDMX: table = new OpenTypeVDMX(this, tag); break;
   856        case OTS_TAG_VORG: table = new OpenTypeVORG(this, tag); break;
   857        case OTS_TAG_VHEA: table = new OpenTypeVHEA(this, tag); break;
   858        case OTS_TAG_VMTX: table = new OpenTypeVMTX(this, tag); break;
   859        default: break;
   860      }
   861    }
   862
   863    if (table) {
   864      Arena arena;
   865      const uint8_t* table_data;
   866      size_t table_length;
   867
   868      if (GetTableData(data, table_entry, &arena, &table_length, &table_data)) {
   869        // FIXME: Parsing some tables will fail if the table is not added to
   870        // m_tables first.
   871        m_tables[tag] = table;
   872        ret = table->Parse(table_data, table_length);
   873        if (!ret) {
   874          m_tables.erase(tag);
   875          delete table;
   876        } else {
   877          file->tables[table_entry] = table;
   878        }
   879      }
   880    }
